#!/bin/bash
# Qwen2.5-VL-3B with HybridKV + DecoupleKV-style K/V merge gated by prompt-level adjacent-K similarity.
#
# Current behavior:
#   - Original HybridKV dynamic/static head classification and budget allocation are kept.
#   - A global simhead gate ranks all KV heads by adjacent K similarity for the current prompt.
#   - Retrieval/dynamic heads selected by the gate merge full history K/V before building the chunk index;
#     unselected retrieval heads use the original HybridKV chunk index.
#   - Pruning/static heads selected by the gate select an expanded candidate set and merge it back to
#     the original per-head budget; unselected pruning heads use original HybridKV pruning.
#   - Default decode keeps FlashAttention without log(group_size) correction; log_count is experimental opt-in.
#
# Usage:
#   cd /root/autodl-tmp/HybridKV-artifact/HybridKV-artifact/scripts
#   conda activate hybridkv
#   LIMIT=500 TASK=vatex_test bash eval/qwen_ratio_hybrid_decouplekv_3b.sh

set -euo pipefail

num_frame=${NUM_FRAME:-64}
limit=${LIMIT:-10000}
task=${TASK:-nextqa_oe_test}
pretrained=${PRETRAINED:-Qwen/Qwen2.5-VL-3B-Instruct}

script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
repo_root="$(cd "${script_dir}/../.." && pwd)"
cd "${repo_root}/scripts"

export METHOD=hybrid_decouplekv
export MODEL_TYPE=${MODEL_TYPE:-qwen2_5_vl-3b}
export PYTHONPATH="${repo_root}:${repo_root}/lmms-eval:${PYTHONPATH:-}"

# Keep the same cache layout as other scripts to avoid re-downloading.
export HF_HOME=${HF_HOME:-$(pwd)/data/huggingface_cache}
export HF_DATASETS_CACHE=${HF_DATASETS_CACHE:-${HF_HOME}/datasets}
export HUGGINGFACE_HUB_CACHE=${HUGGINGFACE_HUB_CACHE:-${HF_HOME}/hub}
export HF_ENDPOINT=${HF_ENDPOINT:-https://hf-mirror.com}
unset HF_HUB_DISABLE_XET

export CUDA_VISIBLE_DEVICES=${CUDA_VISIBLE_DEVICES:-0}
export CUDA_LAUNCH_BLOCKING=${CUDA_LAUNCH_BLOCKING:-0}
export OMP_NUM_THREADS=${OMP_NUM_THREADS:-4}
export DECORD_EOF_RETRY_MAX=${DECORD_EOF_RETRY_MAX:-20480}

# Original HybridKV controls.
export BUDGET_RATIO=${BUDGET_RATIO:-0.10}
export BUDGET=${BUDGET:-1024}
export RATIO=${RATIO:-${BUDGET_RATIO}}
export HEAD_CLASSIFY=${HEAD_CLASSIFY:-head_ada}
export BUDGET_METHOD=${BUDGET_METHOD:-head_ada}

# DecoupleKV merge controls. This cleaned variant never records or applies
# log(group_size); dynamic and static merged caches both use FlashAttention.
export HYBRID_DECOUPLE_CHUNK_SIZE=${HYBRID_DECOUPLE_CHUNK_SIZE:-8}
export HYBRID_DECOUPLE_COMPRESS_RATIO=${HYBRID_DECOUPLE_COMPRESS_RATIO:-0.50}
export K_DIFF_ALPHA=${K_DIFF_ALPHA:-2}
export HYBRID_DECOUPLE_K_DIFF_ALPHA=${HYBRID_DECOUPLE_K_DIFF_ALPHA:-${K_DIFF_ALPHA}}
export HYBRID_DECOUPLE_MAX_GROUP_SIZE=${HYBRID_DECOUPLE_MAX_GROUP_SIZE:-0}
export HYBRID_DECOUPLE_BLOCK_META_WEIGHT=${HYBRID_DECOUPLE_BLOCK_META_WEIGHT:-uniform}
export HYBRID_DECOUPLE_STATIC_MERGE_SCOPE=${HYBRID_DECOUPLE_STATIC_MERGE_SCOPE:-visual}
export HYBRID_DECOUPLE_K_MERGE_SPACE=${HYBRID_DECOUPLE_K_MERGE_SPACE:-${K_MERGE_SPACE:-raw_reapply}}
export HYBRID_DECOUPLE_SIMHEAD_ENABLE=${HYBRID_DECOUPLE_SIMHEAD_ENABLE:-1}
export HYBRID_DECOUPLE_SIMHEAD_MERGE_RATIO=${HYBRID_DECOUPLE_SIMHEAD_MERGE_RATIO:-0.30}
export HYBRID_DECOUPLE_SIMHEAD_SIM_SPACE=${HYBRID_DECOUPLE_SIMHEAD_SIM_SPACE:-raw}
export HYBRID_DECOUPLE_VERBOSE=${HYBRID_DECOUPLE_VERBOSE:-0}
export HYBRIDKV_VERBOSE=${HYBRIDKV_VERBOSE:-0}

merge_score_mode=${HYBRID_DECOUPLE_MERGE_SCORE_MODE:-${DECOUPLE_MERGE_SCORE_MODE:-full}}
run_tag=${RUN_TAG:-}
run_suffix=${run_tag:+_${run_tag}}
out_dir="./logs/${task}/${METHOD}/${num_frame}/nolog_simhead${HYBRID_DECOUPLE_SIMHEAD_MERGE_RATIO}_chunk${HYBRID_DECOUPLE_CHUNK_SIZE}_cr${HYBRID_DECOUPLE_COMPRESS_RATIO}_alpha${HYBRID_DECOUPLE_K_DIFF_ALPHA}_maxgrp${HYBRID_DECOUPLE_MAX_GROUP_SIZE}_kspace${HYBRID_DECOUPLE_K_MERGE_SPACE}_meta${HYBRID_DECOUPLE_BLOCK_META_WEIGHT}_staticscope${HYBRID_DECOUPLE_STATIC_MERGE_SCOPE}_budget${BUDGET_RATIO}_head${HEAD_CLASSIFY}_alloc${BUDGET_METHOD}_limit${limit}${run_suffix}"
mkdir -p "${out_dir}"

if [ "${HYBRID_DECOUPLE_DUMP_MERGE:-0}" = "1" ]; then
    export HYBRID_DECOUPLE_DUMP_MERGE_PATH="${HYBRID_DECOUPLE_DUMP_MERGE_PATH:-${out_dir}/hybrid_decouple_merge_mask.jsonl}"
    if [ "${DRY_RUN:-0}" != "1" ]; then
        : > "${HYBRID_DECOUPLE_DUMP_MERGE_PATH}"
    fi
fi

printf '[Hybrid-DecoupleKV] task=%s limit=%s budget=%s simtop=%s compress=%s alpha=%s score_mode=%s chunk=%s max_group=%s k_merge_space=%s block_meta=%s static_merge_scope=%s correction=none attention=flash
' \
    "${task}" "${limit}" "${BUDGET_RATIO}" "${HYBRID_DECOUPLE_SIMHEAD_MERGE_RATIO}" \
    "${HYBRID_DECOUPLE_COMPRESS_RATIO}" "${HYBRID_DECOUPLE_K_DIFF_ALPHA}" "${merge_score_mode}" "${HYBRID_DECOUPLE_CHUNK_SIZE}" \
    "${HYBRID_DECOUPLE_MAX_GROUP_SIZE}" "${HYBRID_DECOUPLE_K_MERGE_SPACE}" "${HYBRID_DECOUPLE_BLOCK_META_WEIGHT}" "${HYBRID_DECOUPLE_STATIC_MERGE_SCOPE}"

if [ -n "${HYBRID_DECOUPLE_DUMP_MERGE_PATH:-}" ]; then
    echo "[Hybrid-DecoupleKV] merge dump path=${HYBRID_DECOUPLE_DUMP_MERGE_PATH}"
fi

if [ "${DRY_RUN:-0}" = "1" ]; then
    echo "[Hybrid-DecoupleKV] DRY_RUN=1, skip lmms-eval launch."
    exit 0
fi

accelerate launch --num_processes 1 --main_process_port ${PORT:-54483} -m lmms_eval \
    --model qwen2_5_vl \
    --model_args pretrained=${pretrained},max_num_frames=${num_frame},attn_implementation=flash_attention_2,method=${METHOD} \
    --tasks ${task} \
    --batch_size 1 \
    --log_samples \
    --log_samples_suffix qwen2_5_vl \
    --output_path "${out_dir}/eval_outputs" \
    --gen_kwargs temperature=0 \
    --limit ${limit}

#!/bin/bash
# Qwen2.5-VL-3B with SnapKV pruning + prompt-aware adjacent-sim head gate + DecoupleKV-style K/V merge.
#
# Behavior:
#   - SnapKV importance first selects expanded history candidates for every KV head.
#   - Adjacent K similarity is computed on each selected candidate sequence.
#   - Heads are ranked globally across all layers; high-sim heads use K/V mean merge back to the original SnapKV budget.
#   - Low-sim heads fall back to original SnapKV top-k pruning to the same budget.
#   - The recent window is kept uncompressed, as in original SnapKV.
#   - No K-to-V map path is used; final K/V lengths are equal and decode uses FlashAttention without log(group_size).
#
# Usage:
#   cd /root/autodl-tmp/HybridKV-artifact/HybridKV-artifact/scripts
#   conda activate hybridkv
#   LIMIT=500 TASK=vatex_test bash eval/qwen_ratio_snapkv_decouplekv_simhead_3b.sh

set -e

num_frame=${NUM_FRAME:-64}
limit=${LIMIT:-200}
task=${TASK:-nextqa_oe_test}
pretrained=${PRETRAINED:-Qwen/Qwen2.5-VL-3B-Instruct}

script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
repo_root="$(cd "${script_dir}/../.." && pwd)"

export METHOD=snapkv_decouplekv
export METHOD_NAME=snapkv_decouplekv_simhead
export MODEL_TYPE=${MODEL_TYPE:-qwen2_5_vl-3b}
export PYTHONPATH="${repo_root}:${repo_root}/lmms-eval:${PYTHONPATH:-}"

export HF_HOME=$(pwd)/data/huggingface_cache
export HF_DATASETS_CACHE=${HF_HOME}/datasets
export HUGGINGFACE_HUB_CACHE=${HF_HOME}/hub
export HF_ENDPOINT=${HF_ENDPOINT:-https://hf-mirror.com}
unset HF_HUB_DISABLE_XET

export CUDA_VISIBLE_DEVICES=${CUDA_VISIBLE_DEVICES:-0}
export CUDA_LAUNCH_BLOCKING=${CUDA_LAUNCH_BLOCKING:-0}
export OMP_NUM_THREADS=${OMP_NUM_THREADS:-4}
export DECORD_EOF_RETRY_MAX=${DECORD_EOF_RETRY_MAX:-20480}

# Original SnapKV-compatible budget. BUDGET_RATIO controls selected history length;
# final cache length is roughly ceil(T * BUDGET_RATIO) + SNAPKV_DECOUPLE_WINDOW_SIZE.
export BUDGET_RATIO=${BUDGET_RATIO:-0.10}
unset BUDGET

# Prompt-aware head gate. High adjacent-sim heads enable expanded-candidate K/V merge.
export SNAPKV_SIMHEAD_MERGE_RATIO=${SNAPKV_SIMHEAD_MERGE_RATIO:-0}
export SNAPKV_SIMHEAD_SIM_SPACE=${SNAPKV_SIMHEAD_SIM_SPACE:-raw}

# Candidate expansion and adjacent merge. Example: ratio=0.80 selects about
# budget/0.80 history candidates, then enabled heads merge back to budget.
export SNAPKV_DECOUPLE_COMPRESS_RATIO=${SNAPKV_DECOUPLE_COMPRESS_RATIO:-0.90}
export K_DIFF_ALPHA=${K_DIFF_ALPHA:-1}
export SNAPKV_DECOUPLE_SCORE_CORRECTION=${SNAPKV_DECOUPLE_SCORE_CORRECTION:-none}
export SNAPKV_DECOUPLE_ENABLE=${SNAPKV_DECOUPLE_ENABLE:-1}

# SnapKV selector controls.
export SNAPKV_DECOUPLE_WINDOW_SIZE=${SNAPKV_DECOUPLE_WINDOW_SIZE:-32}
export SNAPKV_DECOUPLE_KERNEL_SIZE=${SNAPKV_DECOUPLE_KERNEL_SIZE:-5}
export SNAPKV_DECOUPLE_POOLING=${SNAPKV_DECOUPLE_POOLING:-avgpool}
export SNAPKV_DECOUPLE_GQA_FUNC=${SNAPKV_DECOUPLE_GQA_FUNC:-mean}

merge_score_mode=${SNAPKV_DECOUPLE_MERGE_SCORE_MODE:-${DECOUPLE_MERGE_SCORE_MODE:-full}}
run_tag=${RUN_TAG:-}
run_suffix=${run_tag:+_${run_tag}}
out_dir="./logs/${task}/${METHOD_NAME}/${num_frame}/budget${BUDGET_RATIO}_simtop${SNAPKV_SIMHEAD_MERGE_RATIO}_cr${SNAPKV_DECOUPLE_COMPRESS_RATIO}_alpha${K_DIFF_ALPHA}_sim${SNAPKV_SIMHEAD_SIM_SPACE}_corr${SNAPKV_DECOUPLE_SCORE_CORRECTION}_limit${limit}${run_suffix}"
mkdir -p "${out_dir}"

printf '[SnapKV-DecoupleKV] task=%s limit=%s budget=%s sim_merge_ratio=%s compress_ratio=%s alpha=%s score_mode=%s sim_space=%s correction=none attention=flash\n' \
    "${task}" "${limit}" "${BUDGET_RATIO}" "${SNAPKV_SIMHEAD_MERGE_RATIO}" \
    "${SNAPKV_DECOUPLE_COMPRESS_RATIO}" "${K_DIFF_ALPHA}" "${merge_score_mode}" "${SNAPKV_SIMHEAD_SIM_SPACE}"

if [ "${DRY_RUN:-0}" = "1" ]; then
    echo "[SnapKV-DecoupleKV] DRY_RUN=1, skip lmms-eval launch."
    exit 0
fi

accelerate launch --num_processes 1 --main_process_port ${PORT:-54483} -m lmms_eval \
    --model qwen2_5_vl \
    --model_args pretrained=${pretrained},max_num_frames=${num_frame},attn_implementation=flash_attention_2,method=${METHOD} \
    --tasks ${task} \
    --batch_size 1 \
    --log_samples \
    --log_samples_suffix qwen2_5_vl \
    --output_path "${out_dir}/eval_outputs" \
    --gen_kwargs temperature=0 \
    --limit ${limit}

#!/bin/bash
# Qwen2.5-VL-3B with SparseMM head-adaptive pruning + prompt-aware DecoupleKV-style K/V merge.
#
# Behavior:
#   - SparseMM observation score, visual head score, and head-adaptive budget allocation are preserved.
#   - Low-sim / disabled heads use the original SparseMM descending-score top-k cache order.
#   - High adjacent-K-sim heads select expanded candidates, then K/V-mean merge back to the SparseMM head budget.
#   - Recent window is kept unchanged.
#   - Decode always uses SparseMM's original varlen FlashAttention path; no log(group_size) correction is applied.
#
# Usage:
#   cd /root/autodl-tmp/HybridKV-artifact/HybridKV-artifact/scripts
#   conda activate hybridkv
#   LIMIT=500 TASK=vatex_test bash eval/qwen_ratio_sparsemm_decouplekv_simhead_3b.sh

set -e

num_frame=${NUM_FRAME:-64}
limit=${LIMIT:-200}
task=${TASK:-nextqa_oe_test}

script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
repo_root="$(cd "${script_dir}/../.." && pwd)"

export METHOD=sparsemm_decouplekv
export METHOD_NAME=sparsemm_decouplekv_simhead
export MODEL_TYPE=qwen2_5_vl-3b
export PYTHONPATH="${repo_root}:${repo_root}/lmms-eval:${PYTHONPATH:-}"

export HF_HOME=$(pwd)/data/huggingface_cache
export HF_DATASETS_CACHE=${HF_HOME}/datasets
export HUGGINGFACE_HUB_CACHE=${HF_HOME}/hub
export HF_ENDPOINT=${HF_ENDPOINT:-https://hf-mirror.com}
unset HF_HUB_DISABLE_XET

export CUDA_VISIBLE_DEVICES=${CUDA_VISIBLE_DEVICES:-0}
export CUDA_LAUNCH_BLOCKING=${CUDA_LAUNCH_BLOCKING:-0}
export OMP_NUM_THREADS=${OMP_NUM_THREADS:-4}
export DECORD_EOF_RETRY_MAX=${DECORD_EOF_RETRY_MAX:-20480}

# SparseMM-compatible controls. BUDGET is kept for compatibility with older scripts;
# this implementation uses BUDGET_RATIO for the prompt-length-scaled base capacity.
export BUDGET=${BUDGET:-1024}
export BUDGET_RATIO=${BUDGET_RATIO:-0.10}
export RATIO=${RATIO:-0.10}
export SPARSEMM_DECOUPLE_BUDGET_RATIO=${SPARSEMM_DECOUPLE_BUDGET_RATIO:-${BUDGET_RATIO}}
export SPARSEMM_DECOUPLE_RATIO=${SPARSEMM_DECOUPLE_RATIO:-${RATIO}}
export SPARSEMM_DECOUPLE_HEAD_SCORE=${SPARSEMM_DECOUPLE_HEAD_SCORE:-visual}
export SPARSEMM_DECOUPLE_WINDOW_SIZE=${SPARSEMM_DECOUPLE_WINDOW_SIZE:-32}
export SPARSEMM_DECOUPLE_KERNEL_SIZE=${SPARSEMM_DECOUPLE_KERNEL_SIZE:-5}
export SPARSEMM_DECOUPLE_POOLING=${SPARSEMM_DECOUPLE_POOLING:-avgpool}
export SPARSEMM_DECOUPLE_GQA_FUNC=${SPARSEMM_DECOUPLE_GQA_FUNC:-mean}

# Prompt-aware head gate. High adjacent-sim heads enable expanded-candidate K/V merge.
export SPARSEMM_SIMHEAD_MERGE_RATIO=${SPARSEMM_SIMHEAD_MERGE_RATIO:-0.5}
export SPARSEMM_SIMHEAD_SIM_SPACE=${SPARSEMM_SIMHEAD_SIM_SPACE:-raw}

# Candidate expansion and merge. Example: ratio=0.80 selects about budget/0.80
# candidates per head, then enabled heads merge back to the SparseMM head budget.
export SPARSEMM_DECOUPLE_COMPRESS_RATIO=${SPARSEMM_DECOUPLE_COMPRESS_RATIO:-0.8}
export K_DIFF_ALPHA=${K_DIFF_ALPHA:-0}
export SPARSEMM_DECOUPLE_K_DIFF_ALPHA=${SPARSEMM_DECOUPLE_K_DIFF_ALPHA:-${K_DIFF_ALPHA}}
export SPARSEMM_DECOUPLE_SCORE_CORRECTION=none

run_tag=${RUN_TAG:-}
run_suffix=${run_tag:+_${run_tag}}
out_dir="./logs/${task}/${METHOD_NAME}/${num_frame}/budget${SPARSEMM_DECOUPLE_BUDGET_RATIO}_ratio${SPARSEMM_DECOUPLE_RATIO}_simtop${SPARSEMM_SIMHEAD_MERGE_RATIO}_cr${SPARSEMM_DECOUPLE_COMPRESS_RATIO}_alpha${SPARSEMM_DECOUPLE_K_DIFF_ALPHA}_sim${SPARSEMM_SIMHEAD_SIM_SPACE}_corr${SPARSEMM_DECOUPLE_SCORE_CORRECTION}_attnflash_limit${limit}${run_suffix}"
mkdir -p "${out_dir}"

printf '[SparseMM-DecoupleKV] task=%s limit=%s budget=%s sparse_ratio=%s sim_merge_ratio=%s compress_ratio=%s alpha=%s sim_space=%s correction=none attention=flash\n' \
    "${task}" "${limit}" "${SPARSEMM_DECOUPLE_BUDGET_RATIO}" "${SPARSEMM_DECOUPLE_RATIO}" \
    "${SPARSEMM_SIMHEAD_MERGE_RATIO}" "${SPARSEMM_DECOUPLE_COMPRESS_RATIO}" \
    "${SPARSEMM_DECOUPLE_K_DIFF_ALPHA}" "${SPARSEMM_SIMHEAD_SIM_SPACE}"

if [ "${DRY_RUN:-0}" = "1" ]; then
    echo "[SparseMM-DecoupleKV] DRY_RUN=1, skip lmms-eval launch."
    exit 0
fi

accelerate launch --num_processes 1 --main_process_port ${PORT:-54483} -m lmms_eval \
    --model qwen2_5_vl \
    --model_args pretrained=Qwen/Qwen2.5-VL-3B-Instruct,max_num_frames=${num_frame},attn_implementation=flash_attention_2,method=${METHOD} \
    --tasks ${task} \
    --batch_size 1 \
    --log_samples \
    --log_samples_suffix qwen2_5_vl \
    --output_path "${out_dir}/eval_outputs" \
    --gen_kwargs temperature=0 \
    --limit ${limit}

#!/bin/bash
# Qwen2.5-VL-3B with MadaKV allocation + DecoupleKV-style modality-local merge.
#
# Behavior:
#   - MadaKV current_budget, next-layer budget, and vision/text budget allocation are unchanged.
#   - Within each KV head and modality, expanded candidates are selected by MadaKV scores.
#   - Heads are ranked globally by adjacent K similarity; high-sim heads merge expanded candidates
#     back to the original MadaKV budget, while low-sim heads fall back to MadaKV top-k pruning.
#   - Vision and text candidates are never merged with each other; recent window is kept unchanged.
#   - Decode treats merged K/V as ordinary cache slots and uses FlashAttention without log(group_size).
#
# Usage:
#   cd /root/autodl-tmp/HybridKV-artifact/HybridKV-artifact/scripts
#   conda activate hybridkv
#   LIMIT=500 TASK=vatex_test bash eval/qwen_ratio_madakv_decouplekv_simhead_3b.sh

set -e

num_frame=${NUM_FRAME:-64}
limit=${LIMIT:-20000}
task=${TASK:-nextqa_oe_test}

script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
repo_root="$(cd "${script_dir}/../.." && pwd)"

export METHOD=madakv_decouplekv
export METHOD_NAME=madakv_decouplekv_simhead
export MODEL_TYPE=qwen2_5_vl-3b
export PYTHONPATH="${repo_root}:${repo_root}/lmms-eval:${PYTHONPATH:-}"

export HF_HOME=$(pwd)/data/huggingface_cache
export HF_DATASETS_CACHE=${HF_HOME}/datasets
export HUGGINGFACE_HUB_CACHE=${HF_HOME}/hub
export HF_ENDPOINT=${HF_ENDPOINT:-https://hf-mirror.com}
unset HF_HUB_DISABLE_XET

export CUDA_VISIBLE_DEVICES=${CUDA_VISIBLE_DEVICES:-0}
export CUDA_LAUNCH_BLOCKING=${CUDA_LAUNCH_BLOCKING:-0}
export OMP_NUM_THREADS=${OMP_NUM_THREADS:-4}
export DECORD_EOF_RETRY_MAX=${DECORD_EOF_RETRY_MAX:-20480}

# MadaKV allocation controls. BUDGET_RATIO is the initial per-layer history budget ratio.
export BUDGET_RATIO=${BUDGET_RATIO:-0.10}
export MADAKV_DECOUPLE_BUDGET_RATIO=${MADAKV_DECOUPLE_BUDGET_RATIO:-${BUDGET_RATIO}}
export MADAKV_DECOUPLE_THRESHOLD=${MADAKV_DECOUPLE_THRESHOLD:-0.8}
export MADAKV_DECOUPLE_WINDOW_SIZE=${MADAKV_DECOUPLE_WINDOW_SIZE:-32}
export MADAKV_DECOUPLE_GQA_FUNC=${MADAKV_DECOUPLE_GQA_FUNC:-mean}

# Prompt-aware head gate. High adjacent-sim heads enable expanded-candidate K/V merge.
export MADAKV_SIMHEAD_MERGE_RATIO=${MADAKV_SIMHEAD_MERGE_RATIO:-0.1}
export MADAKV_SIMHEAD_SIM_SPACE=${MADAKV_SIMHEAD_SIM_SPACE:-raw}

# Candidate expansion and adjacent merge. Example: ratio=0.80 selects about
# budget/0.80 candidates inside each modality, then enabled heads merge back.
export MADAKV_DECOUPLE_COMPRESS_RATIO=${MADAKV_DECOUPLE_COMPRESS_RATIO:-0.8}
export K_DIFF_ALPHA=${K_DIFF_ALPHA:-1}
export MADAKV_DECOUPLE_K_DIFF_ALPHA=${MADAKV_DECOUPLE_K_DIFF_ALPHA:-${K_DIFF_ALPHA}}
export MADAKV_DECOUPLE_SCORE_CORRECTION=${MADAKV_DECOUPLE_SCORE_CORRECTION:-none}
export MADAKV_DECOUPLE_ENABLE=${MADAKV_DECOUPLE_ENABLE:-1}

run_tag=${RUN_TAG:-}
run_suffix=${run_tag:+_${run_tag}}
out_dir="./logs/${task}/${METHOD_NAME}/${num_frame}/budget${MADAKV_DECOUPLE_BUDGET_RATIO}_simtop${MADAKV_SIMHEAD_MERGE_RATIO}_cr${MADAKV_DECOUPLE_COMPRESS_RATIO}_alpha${MADAKV_DECOUPLE_K_DIFF_ALPHA}_sim${MADAKV_SIMHEAD_SIM_SPACE}_corr${MADAKV_DECOUPLE_SCORE_CORRECTION}_th${MADAKV_DECOUPLE_THRESHOLD}_limit${limit}${run_suffix}"
mkdir -p "${out_dir}"

printf '[MadaKV-DecoupleKV] task=%s limit=%s budget=%s sim_merge_ratio=%s compress_ratio=%s alpha=%s sim_space=%s threshold=%s correction=none attention=flash\n' \
    "${task}" "${limit}" "${MADAKV_DECOUPLE_BUDGET_RATIO}" "${MADAKV_SIMHEAD_MERGE_RATIO}" \
    "${MADAKV_DECOUPLE_COMPRESS_RATIO}" "${MADAKV_DECOUPLE_K_DIFF_ALPHA}" "${MADAKV_SIMHEAD_SIM_SPACE}" "${MADAKV_DECOUPLE_THRESHOLD}"

if [ "${DRY_RUN:-0}" = "1" ]; then
    echo "[MadaKV-DecoupleKV] DRY_RUN=1, skip lmms-eval launch."
    exit 0
fi

accelerate launch --num_processes 1 --main_process_port ${PORT:-54483} -m lmms_eval \
    --model qwen2_5_vl \
    --model_args pretrained=Qwen/Qwen2.5-VL-3B-Instruct,max_num_frames=${num_frame},attn_implementation=flash_attention_2,method=${METHOD} \
    --tasks ${task} \
    --batch_size 1 \
    --log_samples \
    --log_samples_suffix qwen2_5_vl \
    --output_path "${out_dir}/eval_outputs" \
    --gen_kwargs temperature=0 \
    --limit ${limit}

#!/bin/bash
# Qwen2.5-VL-3B with LookM pruning + prompt-aware adjacent-sim head gate + DecoupleKV-style K/V merge.
#
# Behavior:
#   - First select expanded LookM candidates for every KV head.
#   - Compute adjacent K similarity on the selected candidate sequence for every layer/head.
#   - Globally rank all heads in the prompt; high-sim heads use expanded candidates and K/V merge back to the original budget.
#   - Low-sim heads keep original LookM pruning to the same budget.
#   - Prefill output still uses full-KV flash attention; compressed KV is only used as decode cache.
#
# Usage:
#   cd /root/autodl-tmp/HybridKV-artifact/HybridKV-artifact/scripts
#   conda activate hybridkv
#   LIMIT=500 TASK=vatex_test bash eval/qwen_ratio_lookm_decouplekv_3b.sh

set -e

num_frame=${NUM_FRAME:-64}
limit=${LIMIT:-9000}
task=${TASK:-vatex_test}

script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
repo_root="$(cd "${script_dir}/../.." && pwd)"

export METHOD=lookm_decouplekv
export MODEL_TYPE=qwen2_5_vl-3b
export PYTHONPATH="${repo_root}:${repo_root}/lmms-eval:${PYTHONPATH:-}"

export HF_HOME=$(pwd)/data/huggingface_cache
export HF_DATASETS_CACHE=${HF_HOME}/datasets
export HUGGINGFACE_HUB_CACHE=${HF_HOME}/hub
export HF_ENDPOINT=${HF_ENDPOINT:-https://hf-mirror.com}
unset HF_HUB_DISABLE_XET

export CUDA_VISIBLE_DEVICES=${CUDA_VISIBLE_DEVICES:-0}
export CUDA_LAUNCH_BLOCKING=${CUDA_LAUNCH_BLOCKING:-0}
export OMP_NUM_THREADS=${OMP_NUM_THREADS:-4}
export DECORD_EOF_RETRY_MAX=${DECORD_EOF_RETRY_MAX:-20480}

# Original LookM-compatible controls.
export BUDGET=${BUDGET:-1024}
export BUDGET_RATIO=${BUDGET_RATIO:-0.10}
export RATIO=${RATIO:-${BUDGET_RATIO}}
export LOOKM_DECOUPLE_BUDGET_RATIO=${LOOKM_DECOUPLE_BUDGET_RATIO:-${BUDGET_RATIO}}
export LOOKM_DECOUPLE_WINDOW_SIZE=${LOOKM_DECOUPLE_WINDOW_SIZE:-32}
export LOOKM_DECOUPLE_TEXT_PRIORITY=${LOOKM_DECOUPLE_TEXT_PRIORITY:-1}
export LOOKM_DECOUPLE_GQA_FUNC=${LOOKM_DECOUPLE_GQA_FUNC:-mean}

# Prompt-aware head gate. High adjacent-sim heads enable K/V merge.
export LOOKM_SIMHEAD_MERGE_RATIO=${LOOKM_SIMHEAD_MERGE_RATIO:-0.50}
export LOOKM_SIMHEAD_SIM_SPACE=${LOOKM_SIMHEAD_SIM_SPACE:-raw}

# Candidate expansion and adjacent merge.
export LOOKM_DECOUPLE_COMPRESS_RATIO=${LOOKM_DECOUPLE_COMPRESS_RATIO:-0.80}
export K_DIFF_ALPHA=${K_DIFF_ALPHA:-0}
export LOOKM_DECOUPLE_K_DIFF_ALPHA=${LOOKM_DECOUPLE_K_DIFF_ALPHA:-${K_DIFF_ALPHA}}
export LOOKM_DECOUPLE_SCORE_CORRECTION=${LOOKM_DECOUPLE_SCORE_CORRECTION:-none}
export LOOKM_DECOUPLE_ENABLE=${LOOKM_DECOUPLE_ENABLE:-1}

out_dir="./logs/${task}/${METHOD}/${num_frame}/budget${LOOKM_DECOUPLE_BUDGET_RATIO}_simtop${LOOKM_SIMHEAD_MERGE_RATIO}_cr${LOOKM_DECOUPLE_COMPRESS_RATIO}_alpha${LOOKM_DECOUPLE_K_DIFF_ALPHA}_sim${LOOKM_SIMHEAD_SIM_SPACE}_corr${LOOKM_DECOUPLE_SCORE_CORRECTION}_limit${limit}"
mkdir -p "${out_dir}"

printf '[LookM-DecoupleKV] task=%s limit=%s budget=%s sim_merge_ratio=%s compress_ratio=%s alpha=%s sim_space=%s\n' \
    "${task}" "${limit}" "${LOOKM_DECOUPLE_BUDGET_RATIO}" "${LOOKM_SIMHEAD_MERGE_RATIO}" \
    "${LOOKM_DECOUPLE_COMPRESS_RATIO}" "${LOOKM_DECOUPLE_K_DIFF_ALPHA}" "${LOOKM_SIMHEAD_SIM_SPACE}"

if [ "${DRY_RUN:-0}" = "1" ]; then
    echo "[LookM-DecoupleKV] DRY_RUN=1, skip lmms-eval launch."
    exit 0
fi

accelerate launch --num_processes 1 --main_process_port ${PORT:-54483} -m lmms_eval \
    --model qwen2_5_vl \
    --model_args pretrained=Qwen/Qwen2.5-VL-3B-Instruct,max_num_frames=${num_frame},attn_implementation=flash_attention_2,method=${METHOD} \
    --tasks ${task} \
    --batch_size 1 \
    --log_samples \
    --log_samples_suffix qwen2_5_vl \
    --output_path "${out_dir}/eval_outputs" \
    --gen_kwargs temperature=0 \
    --limit ${limit}

#!/usr/bin/env bash
set -euo pipefail

ROOT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)
CONDA_ENV=${CONDA_ENV:-hybridkv}
MODEL=${MODEL:-Qwen/Qwen2.5-VL-3B-Instruct}
TASKS=${TASKS:-"vatex_test nextqa_oe_test"}
LIMIT=${LIMIT:-200}
NUM_FRAMES=${NUM_FRAMES:-64}
GPU=${GPU:-0}
PORT=${PORT:-54583}

export METHOD=asymkv_official
export BUDGET=${BUDGET:-1024}
export BUDGET_RATIO=${BUDGET_RATIO:-0.10}
export RATIO=${RATIO:-0.10}
export MASK_RATIO=${MASK_RATIO:-0.10}
export ASYMKV_START_SIZE=${ASYMKV_START_SIZE:-32}
export ASYMKV_CHUNK_SIZE=${ASYMKV_CHUNK_SIZE:-512}

export CUDA_VISIBLE_DEVICES=${GPU}
if [[ ! "${OMP_NUM_THREADS:-}" =~ ^[1-9][0-9]*$ ]]; then
    export OMP_NUM_THREADS=4
fi
export DECORD_EOF_RETRY_MAX=${DECORD_EOF_RETRY_MAX:-20480}
export PYTHONPATH="${ROOT_DIR}:${ROOT_DIR}/lmms-eval${PYTHONPATH:+:${PYTHONPATH}}"
export HF_HOME=${HF_HOME:-${ROOT_DIR}/scripts/data/huggingface_cache}
export HF_DATASETS_CACHE=${HF_DATASETS_CACHE:-${HF_HOME}/datasets}
export HUGGINGFACE_HUB_CACHE=${HUGGINGFACE_HUB_CACHE:-${HF_HOME}/hub}

MODEL_SLUG=${MODEL//\//__}
OUTPUT_ROOT=${OUTPUT_ROOT:-${ROOT_DIR}/scripts/logs/asymkv_official}

cd "${ROOT_DIR}"
for TASK in ${TASKS}; do
    TASK_OUTPUT="${OUTPUT_ROOT}/${TASK}/${MODEL_SLUG}/frames${NUM_FRAMES}/budget${BUDGET_RATIO}"
    mkdir -p "${TASK_OUTPUT}"
    export ASYMKV_AUDIT_PATH="${TASK_OUTPUT}/asymkv_official_audit.jsonl"
    if [[ "${RESET_AUDIT:-1}" == "1" ]]; then
        : > "${ASYMKV_AUDIT_PATH}"
    fi

    conda run --no-capture-output -n "${CONDA_ENV}" \
        accelerate launch \
        --num_processes 1 \
        --main_process_port "${PORT}" \
        -m lmms_eval \
        --model qwen2_5_vl \
        --model_args "pretrained=${MODEL},max_num_frames=${NUM_FRAMES},attn_implementation=flash_attention_2,method=asymkv_official,budget=${BUDGET},ratio=${RATIO},mask_ratio=${MASK_RATIO}" \
        --tasks "${TASK}" \
        --batch_size 1 \
        --log_samples \
        --log_samples_suffix qwen2_5_vl_asymkv_official \
        --output_path "${TASK_OUTPUT}" \
        --gen_kwargs temperature=0 \
        --limit "${LIMIT}"

    PORT=$((PORT + 1))
done
